import math
def control(o):
    h=math.radians(o['hitch_deg'])
    cam=o['views'].get('camera')
    if not cam: return (2.4*o['hitch_deg'],-0.45,-23)
    sides=[[],[]]
    for b,d in cam.get('walls',[]):
        b=math.radians(b); x=d*math.cos(b); y=d*math.sin(b)
        s=-math.cos(h)*x+math.sin(h)*y
        l=math.sin(h)*x+math.cos(h)*y
        if s>0.3: sides[0 if l<0 else 1].append((s,l))
    def val(a,s):
        a=sorted(a)
        if not a:return None
        for p,q in zip(a,a[1:]):
            if p[0]<=s<=q[0]:return p[1]+(q[1]-p[1])*(s-p[0])/max(.001,q[0]-p[0])
        p=min(a,key=lambda p:abs(p[0]-s))
        return p[1] if abs(p[0]-s)<1.4 else None
    L=3.8
    a=val(sides[0],L); b=val(sides[1],L)
    e=(a+b)/2 if a is not None and b is not None else 0
    desired=math.degrees(math.atan(7.3*e/(L*L)))
    desired=max(-30,min(30,desired))
    steer=max(-34,min(34,2.4*o['hitch_deg']-1.7*desired))
    return (steer,-0.65,-23)

