import math
phase=0
distance=0.0
done=False
def control(obs):
 global phase,distance,done
 v=obs['motion']['v_mps']
 if phase==0:
  distance+=max(0,v)*obs['dt']
  if distance<0.38:
   return (45,0.18,-55)
  phase=1
  distance=0.0
 if phase==1:
  distance+=max(0,-v)*obs['dt']
  h=obs['hitch_deg']
  desired=48.0
  feed=math.degrees(math.atan(1.25*math.sin(math.radians(desired))/(0.85+0.3*math.cos(math.radians(desired)))))
  steer=max(-20,min(45,feed+3.0*(h-desired)))
  if distance<0.65 and h<56:
   return (steer,-0.14,-65)
  phase=2
 if abs(v)<0.02 and obs['head']['settled'] and not done:
  done=True
  print(obs)
  wake('Inspect clearance after tighter reposition')
 return (20,0,-65)

