import math
n=0
filtered=0.0
def control(obs):
 global n,filtered
 n+=1
 cam=obs['views'].get('camera')
 h=obs['hitch_deg']
 if not cam: return (h*1.5,0,-41)
 theta=math.radians(obs['rig']['trailer_heading_deg'])
 sides=[[],[]]
 for b,d in cam['walls']:
  b=math.radians(b)
  x=d*math.cos(b); y=d*math.sin(b)
  u=-x*math.cos(theta)-y*math.sin(theta)
  w=-x*math.sin(theta)+y*math.cos(theta)
  if 0<u<14 and abs(w)>0.6:
   sides[0 if w<0 else 1].append((u,w))
 def estimate(points,u):
  points=sorted(points)
  if not points:return None
  for a,b in zip(points,points[1:]):
   if a[0]<=u<=b[0]:return a[1]+(b[1]-a[1])*(u-a[0])/max(.01,b[0]-a[0])
  p=min(points,key=lambda p:abs(p[0]-u))
  return p[1] if abs(p[0]-u)<3 else None
 centers=[]
 for u in [4,6,8]:
  a=estimate(sides[0],u);b=estimate(sides[1],u)
  if a is not None and b is not None:centers.append((u,(a+b)/2))
 if not centers:
  wake('Need a clearer view of the rails')
  return (h,0,-41)
 angle=sum(math.degrees(math.atan2(w,u)) for u,w in centers)/len(centers)
 filtered=.8*filtered+.2*angle
 steer=max(-40,min(40,1.65*h-3.0*filtered))
 if n%100==0:print('h',round(h,1),'aim',round(filtered,1),'steer',round(steer,1),'remaining',obs['progress']['remaining'])
 return (steer,-0.85,-41)

